package com.interviewcoach.api;
import com.interviewcoach.repo.*;import com.interviewcoach.model.*;import com.fasterxml.jackson.databind.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class DashboardController {private final UserRepo users;private final InterviewRepo interviews;private final ResumeRepo resumes;private final LearningProgressRepo progress;private final ObjectMapper mapper;
 public DashboardController(UserRepo u,InterviewRepo i,ResumeRepo r,LearningProgressRepo p,ObjectMapper m){users=u;interviews=i;resumes=r;progress=p;mapper=m;}
 @GetMapping("/dashboard")public Map<String,Object> dashboard(){User u=users.findById(ApiSupport.uid()).orElseThrow();List<Interview> all=interviews.findByUserIdOrderByStartedAtDesc(u.id);List<Integer> scores=new ArrayList<>();for(Interview i:all)if(i.report!=null)try{scores.add(mapper.readTree(i.report).path("overallScore").asInt());}catch(Exception ignored){}return Map.of("name",u.name,"email",u.email,"targetRole",u.targetRole,"interviewCount",scores.size(),"averageScore",scores.stream().mapToInt(x->x).average().orElse(0),"latestScore",scores.isEmpty()?0:scores.get(0),"scores",scores,"resumeUploaded",resumes.findFirstByUserIdOrderByCreatedAtDesc(u.id).isPresent(),"aiConfigured",System.getenv("OPENAI_API_KEY")!=null&&!System.getenv("OPENAI_API_KEY").isBlank());}
 @PutMapping("/profile")public Map<String,Object> profile(@RequestBody Map<String,String> body){User u=users.findById(ApiSupport.uid()).orElseThrow();String role=body.getOrDefault("targetRole",u.targetRole);if(role.length()>120)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Role too long");u.targetRole=role;users.save(u);return Map.of("targetRole",u.targetRole);}
 @GetMapping("/resources")public List<Map<String,String>> resources(){return List.of(Map.of("id","java","title","Java Tutorials","provider","Oracle","url","https://dev.java/learn/","skill","Java fundamentals"),Map.of("id","spring","title","Spring Guides","provider","Spring","url","https://spring.io/guides","skill","Backend development"),Map.of("id","react","title","Learn React","provider","React","url","https://react.dev/learn","skill","Frontend development"),Map.of("id","python","title","Python Tutorial","provider","Python Software Foundation","url","https://docs.python.org/3/tutorial/","skill","Python programming"),Map.of("id","sql","title","PostgreSQL Tutorial","provider","PostgreSQL","url","https://www.postgresql.org/docs/current/tutorial.html","skill","SQL fundamentals"));}
 @PutMapping("/resources/{resourceId}")public Map<String,String> progress(@PathVariable String resourceId,@RequestBody Map<String,String> body){if(!Set.of("java","spring","react","python","sql").contains(resourceId))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Unknown resource");String status=body.getOrDefault("status","PLANNED");if(!Set.of("PLANNED","IN_PROGRESS","COMPLETED").contains(status))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Invalid status");LearningProgress row=progress.findByUserIdAndResourceId(ApiSupport.uid(),resourceId).orElseGet(()->{LearningProgress p=new LearningProgress();p.user=users.getReferenceById(ApiSupport.uid());p.resourceId=resourceId;return p;});row.status=status;progress.save(row);return Map.of("status",status);}
}
